type Status=Active | Archived | Pending
type Pack={b:owned buffer,p:&mut int}
fn pick(s:Status,x:&mut int,y:&mut int)->Pack
ensures true
{return match s {Active=>Pack(buffer(1),x),_=>Pack(buffer(2),y)}}

